// Created: 2026-08-25

/**
 * empty-result-detector (#3739)
 *
 * The bug: a subagent completes with `status: completed` and delivers no final
 * assistant text, so the parent sees silence and reads it as an empty finding
 * rather than a failed delegation.
 *
 * The three-way verdict is the point of these tests. `unobservable` must never
 * collapse into `empty`: reporting an unreadable transcript as an empty result
 * would fire on every row and train the reader to ignore the warning, which is
 * exactly how output-validator became a kill-switch (#3200).
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { HookInput } from '../../types.js';
import {
  emptyResultDetector,
  classifyTranscript,
} from '../../subagent-stop/empty-result-detector.js';

let dir: string;
beforeEach(() => { dir = mkdtempSync(join(tmpdir(), 'erd-')); });
afterEach(() => { rmSync(dir, { recursive: true, force: true }); });

/** Build a transcript from a compact block spec, mirroring CC's jsonl shape. */
function transcript(blocks: Array<{ type: string; text?: string }>): string {
  const p = join(dir, `t-${Math.random().toString(36).slice(2)}.jsonl`);
  const lines = blocks.map((b) =>
    JSON.stringify({
      type: b.type === 'text' ? 'assistant' : 'assistant',
      message: { content: [b.type === 'text' ? { type: 'text', text: b.text ?? '' } : { type: b.type }] },
    }),
  );
  writeFileSync(p, `${lines.join('\n')}\n`);
  return p;
}

function stopInput(transcriptPath?: string, agent = 'ork:code-quality-reviewer'): HookInput {
  return {
    tool_name: '',
    session_id: 's1',
    tool_input: {},
    agent_transcript_path: transcriptPath,
    subagent_type: agent,
  } as unknown as HookInput;
}

describe('classifyTranscript', () => {
  it('a transcript ending in assistant text is delivered', () => {
    const p = transcript([
      { type: 'tool_use' },
      { type: 'tool_result' },
      { type: 'text', text: 'Here is the full review report, with findings and a verdict.' },
    ]);
    const r = classifyTranscript(p);
    expect(r.verdict).toBe('delivered');
    expect(r.lastBlock).toBe('text');
    expect(r.finalTextLength).toBeGreaterThan(0);
  });

  // The dominant real shape: 68 of the 97 silent completions measured on this
  // machine end on a tool_result.
  it('a transcript ending on tool_result is empty', () => {
    const p = transcript([
      { type: 'text', text: 'I will start by pulling the diff.' },
      { type: 'tool_use' },
      { type: 'tool_result' },
    ]);
    const r = classifyTranscript(p);
    expect(r.verdict).toBe('empty');
    expect(r.lastBlock).toBe('tool_result');
  });

  it('a transcript ending on tool_use or thinking is empty', () => {
    for (const last of ['tool_use', 'thinking']) {
      const r = classifyTranscript(transcript([{ type: 'text', text: 'ok' }, { type: last }]));
      expect(r.verdict, `ending on ${last}`).toBe('empty');
    }
  });

  // A preamble followed by silence is the exact shape reported in #3739: the
  // parent received the opening line and nothing else.
  it('preamble text followed by a tool call is empty, not delivered', () => {
    const p = transcript([
      { type: 'text', text: "I'll start by pulling the diff and the repo conventions." },
      { type: 'tool_use' },
    ]);
    expect(classifyTranscript(p).verdict).toBe('empty');
  });

  it('an empty text block does not count as a delivered message', () => {
    const p = transcript([{ type: 'tool_result' }, { type: 'text', text: '   ' }]);
    expect(classifyTranscript(p).verdict).toBe('empty');
  });

  // --- the distinction that keeps this hook from becoming a kill-switch ---

  it('a missing path is unobservable, NOT empty', () => {
    const r = classifyTranscript(undefined);
    expect(r.verdict).toBe('unobservable');
    expect(r.reason).toMatch(/no agent_transcript_path/);
  });

  it('a path that is not on disk is unobservable, NOT empty', () => {
    const r = classifyTranscript(join(dir, 'nope.jsonl'));
    expect(r.verdict).toBe('unobservable');
    expect(r.reason).toMatch(/not on disk/);
  });

  it('a transcript with no content blocks is unobservable, NOT empty', () => {
    const p = join(dir, 'blank.jsonl');
    writeFileSync(p, '{"type":"attachment"}\n');
    expect(classifyTranscript(p).verdict).toBe('unobservable');
  });

  it('unparsable leading lines are skipped, not treated as evidence', () => {
    const p = join(dir, 'trunc.jsonl');
    writeFileSync(p, '{"message":{"content":[{"ty\n' +
      JSON.stringify({ message: { content: [{ type: 'text', text: 'a real closing report here' }] } }) + '\n');
    expect(classifyTranscript(p).verdict).toBe('delivered');
  });
});

describe('emptyResultDetector', () => {
  it('stays silent when the agent delivered a report', () => {
    const p = transcript([{ type: 'text', text: 'A complete report with a verdict line.' }]);
    const r = emptyResultDetector(stopInput(p));
    expect(r.continue).toBe(true);
    expect(r.systemMessage).toBeUndefined();
  });

  it('stays silent when the transcript cannot be read', () => {
    const r = emptyResultDetector(stopInput(undefined));
    expect(r.continue).toBe(true);
    expect(r.systemMessage).toBeUndefined();
  });

  it('emits a loud marker naming the agent when the result is empty', () => {
    const p = transcript([{ type: 'tool_use' }, { type: 'tool_result' }]);
    const r = emptyResultDetector(stopInput(p, 'ork:code-quality-reviewer'));
    expect(r.systemMessage).toBeDefined();
    expect(r.systemMessage).toContain('EMPTY RESULT');
    expect(r.systemMessage).toContain('ork:code-quality-reviewer');
    expect(r.systemMessage).toContain('tool_result');
    // The marker must tell the reader what NOT to do, since the failure mode is
    // a caller who fills the silence with a fabricated summary.
    expect(r.systemMessage).toMatch(/FAILED delegation/);
    expect(r.systemMessage).toMatch(/do not write the report/i);
  });

  // Never block: the dispatcher short-circuits on continue:false and would
  // starve every hook behind this one, and stop hooks that re-feed the model
  // caused an infinite loop in CC 2.1.78.
  it('never blocks, in any verdict', () => {
    const cases = [
      transcript([{ type: 'text', text: 'delivered report text' }]),
      transcript([{ type: 'tool_result' }]),
      undefined,
    ];
    for (const p of cases) {
      expect(emptyResultDetector(stopInput(p)).continue).toBe(true);
    }
  });
});
